// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;


//
// Como en una prueba de Remix todas las llamadas salen del contrato de test, cada
// participante (creador y mecenas) se simula con un contrato "Actor" propio, con su
// propia dirección y su propio saldo de ETH.
//
// Las pruebas que dependen del paso del tiempo (campaña fallida, abandono, cierre de
// votación por plazo) no se pueden hacer aquí; están en test/crowdfunding.test.js.

import "remix_tests.sol";
import "CrowdfundingHitos.sol";

contract Actor {
    CrowdfundingHitos public cf;

    constructor(CrowdfundingHitos _cf) payable { cf = _cf; }
    receive() external payable {}

    function crear(uint96 objetivo, uint40 duracion, uint96[] memory importes) external returns (uint256) {
        return cf.crearCampana(objetivo, duracion, importes);
    }
    function aportar(uint256 id, uint256 valor) external { cf.aportar{value: valor}(id); }
    function solicitar(uint256 id) external { cf.solicitarHito(id); }
    function votar(uint256 id, bool aFavor) external { cf.votar(id, aFavor); }
    function reembolsar(uint256 id) external { cf.reembolsar(id); }
    function retirar() external { cf.retirar(); }
    function cancelar(uint256 id) external { cf.cancelarCampana(id); }
}

contract CrowdfundingHitosTest {
    CrowdfundingHitos cf;
    Actor creador;
    Actor ana;   // aporta 1500 (50 %)
    Actor beto;  // aporta 1000 (33 %)
    Actor carla; // aporta  500 (17 %)

    uint96 constant OBJETIVO = 3000;
    uint256 constant SALDO_INICIAL = 10000;

    /// #value: 1000000
    function beforeAll() public payable {
        cf = new CrowdfundingHitos();
    }

    /// Cada prueba trabaja con participantes nuevos para ser independiente.
    function beforeEach() public {
        creador = new Actor(cf);
        ana = new Actor{value: SALDO_INICIAL}(cf);
        beto = new Actor{value: SALDO_INICIAL}(cf);
        carla = new Actor{value: SALDO_INICIAL}(cf);
    }

    // ------------------------------------------------------------- utilidades

    function _hitos() internal pure returns (uint96[] memory h) {
        h = new uint96[](3);
        h[0] = 1000; h[1] = 1000; h[2] = 1000;
    }

    function _crear() internal returns (uint256) {
        return creador.crear(OBJETIVO, 1 days, _hitos());
    }

    function _crearYFinanciar() internal returns (uint256 id) {
        id = _crear();
        ana.aportar(id, 1500);
        beto.aportar(id, 1000);
        carla.aportar(id, 500);
    }

    function _estado(uint256 id) internal view returns (uint256) {
        (, , , , CrowdfundingHitos.Estado e, , , , ) = cf.campanas(id);
        return uint256(e);
    }

    function _liberado(uint256 id) internal view returns (uint256) {
        (, , , , , , , , uint96 liberado) = cf.campanas(id);
        return liberado;
    }

    function _recaudado(uint256 id) internal view returns (uint256) {
        (, , , , , , uint96 recaudado, , ) = cf.campanas(id);
        return recaudado;
    }

    // ----------------------------------------------------------------- creación

    function testCrearCampana() public {
        uint256 id = _crear();
        (address c, , uint8 numHitos, uint8 hitoActual, , uint96 objetivo, , , ) = cf.campanas(id);
        Assert.equal(c, address(creador), "El creador no coincide");
        Assert.equal(uint256(numHitos), 3, "Debe tener 3 hitos");
        Assert.equal(uint256(hitoActual), 0, "Debe empezar en el hito 0");
        Assert.equal(uint256(objetivo), 3000, "Objetivo incorrecto");
        Assert.equal(_estado(id), 0, "Debe estar en Financiacion");
    }

    function testHitosQueNoSumanElObjetivoRevierte() public {
        uint96[] memory h = new uint96[](2);
        h[0] = 1000; h[1] = 1000; // suman 2000, objetivo 3000
        try creador.crear(OBJETIVO, 1 days, h) {
            Assert.ok(false, "Deberia revertir");
        } catch {
            Assert.ok(true, "Revierte correctamente");
        }
    }

    // ------------------------------------------------------------- financiación

    function testFinanciacionCompletaLiberaPrimerHito() public {
        uint256 id = _crearYFinanciar();
        Assert.equal(_estado(id), 1, "Debe pasar a EnCurso");
        Assert.equal(_recaudado(id), 3000, "Recaudado incorrecto");
        Assert.equal(_liberado(id), 1000, "Debe liberar el primer hito");
        Assert.equal(cf.saldoCreador(address(creador)), 1000, "Saldo del creador incorrecto");
        Assert.equal(address(cf).balance >= 3000, true, "El contrato custodia los fondos");
    }

    function testAportacionQueExcedeObjetivoRevierte() public {
        uint256 id = _crear();
        ana.aportar(id, 2500);
        try beto.aportar(id, 1000) {
            Assert.ok(false, "Deberia revertir por exceder el objetivo");
        } catch {
            Assert.ok(true, "Revierte correctamente");
        }
    }

    function testCreadorNoPuedeAportar() public {
        uint256 id = _crear();
        // el contrato Actor del creador no tiene ETH: se le envía antes
        (bool ok, ) = address(creador).call{value: 100}("");
        Assert.ok(ok, "Fondeo del creador");
        try creador.aportar(id, 100) {
            Assert.ok(false, "El creador no deberia poder aportar");
        } catch {
            Assert.ok(true, "Revierte correctamente");
        }
    }

    // ---------------------------------------------------------------- votación

    function testHitoAprobadoPorMayoria() public {
        uint256 id = _crearYFinanciar();
        creador.solicitar(id);
        Assert.equal(_estado(id), 2, "Debe estar en Votacion");

        ana.votar(id, true);   // 1500 de 3000: aún no es mayoría absoluta
        Assert.equal(_estado(id), 2, "Todavia en Votacion");
        beto.votar(id, true);  // 2500 de 3000: aprobado de forma anticipada

        Assert.equal(_estado(id), 1, "Debe volver a EnCurso");
        Assert.equal(_liberado(id), 2000, "Debe haber liberado dos hitos");

        uint256 antes = address(creador).balance;
        creador.retirar();
        Assert.equal(address(creador).balance - antes, 2000, "El creador retira 2000");
        Assert.equal(cf.saldoCreador(address(creador)), 0, "Saldo a cero tras retirar");
    }

    function testNoSePuedeVotarDosVeces() public {
        uint256 id = _crearYFinanciar();
        creador.solicitar(id);
        carla.votar(id, true);
        try carla.votar(id, true) {
            Assert.ok(false, "Doble voto deberia revertir");
        } catch {
            Assert.ok(true, "Revierte correctamente");
        }
    }

    function testQuienNoAportoNoPuedeVotar() public {
        uint256 id = _crearYFinanciar();
        creador.solicitar(id);
        Actor extrano = new Actor(cf);
        try extrano.votar(id, true) {
            Assert.ok(false, "Un no-mecenas no deberia votar");
        } catch {
            Assert.ok(true, "Revierte correctamente");
        }
    }

    function testSoloElCreadorSolicitaHito() public {
        uint256 id = _crearYFinanciar();
        try ana.solicitar(id) {
            Assert.ok(false, "Solo el creador puede solicitar");
        } catch {
            Assert.ok(true, "Revierte correctamente");
        }
    }

    // ------------------------------------------------- rechazo y reembolsos

    function testHitoRechazadoYReembolsoProporcional() public {
        uint256 id = _crearYFinanciar();
        creador.solicitar(id);
        ana.votar(id, false); // 1500 de 3000 en contra: ya no puede aprobarse
        Assert.equal(_estado(id), 4, "Debe quedar Cancelada");

        // Quedan 2000 sin liberar, que se reparten según lo aportado
        uint256 antesAna = address(ana).balance;
        uint256 antesBeto = address(beto).balance;
        uint256 antesCarla = address(carla).balance;
        ana.reembolsar(id);
        beto.reembolsar(id);
        carla.reembolsar(id);
        Assert.equal(address(ana).balance - antesAna, 1000, "Ana: 1500*2000/3000");
        Assert.equal(address(beto).balance - antesBeto, 666, "Beto: 1000*2000/3000");
        Assert.equal(address(carla).balance - antesCarla, 333, "Carla: 500*2000/3000");
    }

    function testNoSePuedeReembolsarDosVeces() public {
        uint256 id = _crearYFinanciar();
        creador.cancelar(id);
        ana.reembolsar(id);
        try ana.reembolsar(id) {
            Assert.ok(false, "Doble reembolso deberia revertir");
        } catch {
            Assert.ok(true, "Revierte correctamente");
        }
    }

    function testNoHayReembolsoMientrasElProyectoAvanza() public {
        uint256 id = _crearYFinanciar();
        try ana.reembolsar(id) {
            Assert.ok(false, "No debe haber reembolso en EnCurso");
        } catch {
            Assert.ok(true, "Revierte correctamente");
        }
    }

    // ------------------------------------------------------------ flujo completo

    function testFlujoCompletoHastaFinalizar() public {
        uint256 id = _crearYFinanciar();
        for (uint256 i = 0; i < 2; i++) {
            creador.solicitar(id);
            ana.votar(id, true);
            beto.votar(id, true);
        }
        Assert.equal(_estado(id), 3, "Debe quedar Finalizada");
        Assert.equal(_liberado(id), 3000, "Todo liberado");

        uint256 antes = address(creador).balance;
        creador.retirar();
        Assert.equal(address(creador).balance - antes, 3000, "El creador recibe el total");
    }
}

